          lockedGate = null;
          phase = 'align';
          settle = 0;
        }
      } else if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (phase === 'align') {
          target = { x: gate.x - 0.42, y: gate.y, z: gate.z };
          const dist = Math.hypot(target.x - p.x, target.y - p.y, target.z - p.z);
          const spd = Math.hypot(vf.x, vf.y, vf.z);
          const gustTransient = Math.hypot(dFast.x - dSlow.x, dFast.z - dSlow.z);
          if (
            dist < 0.11 &&
            Math.abs(gate.y - p.y) < 0.09 &&
            Math.abs(gate.z - p.z) < 0.055 &&
            spd < 0.32 &&
            gustTransient < 1.1
          ) {
            settle++;
          } else {
            settle = Math.max(0, settle - 1);
          }
          if (settle > 12) {
            phase = 'cross';
            settle = 0;
            intPos.x = 0;
          }
        }
        if (phase === 'cross') {
          const dx = gate.x - p.x;
          // Predictive cross abort before committing into the gate plane
          if (dx > 0.055) {
