        }
      }

      // Smooth ref filter
      const alphaRef = phase === 'cross' || lockedGate ? 0.18 : 0.12;
      ref.x += clamp(target.x - ref.x, -0.22, 0.22) * alphaRef / 0.12;
      ref.y += clamp(target.y - ref.y, -0.18, 0.18) * alphaRef / 0.12;
      ref.z += clamp(target.z - ref.z, -0.20, 0.20) * alphaRef / 0.12;

