      if (Math.abs(eyRaw) < 0.45 && p.y > 0.085) {
        intPos.y = clamp(intPos.y + eyRaw * dt, -0.45, 0.45);
      }

      const ex = ref.x - p.x;
      const ey = ref.y - p.y;
      const ez = ref.z - p.z;

      const inGateCorridor = (phase === 'cross' || lockedGate !== null) && obs.gateIndex < 3;
      const kpZ = inGateCorridor ? 7.2 : 5.2;
      const kdZ = inGateCorridor ? 4.4 : 3.8;
      const kpX = 5.0;
      const kdX = 3.7;

      const distX = dSlow.x + 1.15 * (dFast.x - dSlow.x);
      const distY = 0.65 * dSlow.y + 0.35 * dFast.y;
      const distZ = dSlow.z + 1.25 * (dFast.z - dSlow.z);

