  let intPos = { x: 0, y: 0, z: 0 };
  let ref = { x: 0, y: 0, z: 0 };

  let activeGateIndex = 0;
  let lastGate = null;
  let lockedGate = null;
  let phase = 'align';
  let settle = 0;
  let rampY = 0.75;

