export default function makeController() {
  const dt = 0.01;
  const g = 9.81;
  const massNom = 0.725;
  const dragNom = 0.42 / massNom;
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  let initialized = false;
  let vf = { x: 0, y: 0, z: 0 };
  let prevVf = { x: 0, y: 0, z: 0 };
  let aExpFilt = { x: 0, y: 0, z: 0 };
  let dFast = { x: 0, y: 0, z: 0 };
  let dSlow = { x: 0, y: 0, z: 0 };
  let motorEst = (massNom * g) / 16;

  let intYaw = 0;
  let intPos = { x: 0, y: 0, z: 0 };
  let ref = { x: 0, y: 0, z: 0 };

  let activeGateIndex = 0;
  let lastGate = null;
  let lockedGate = null;
  let phase = 'align';
  let settle = 0;
  let rampY = 0.75;

  return {
    step(obs) {
      const p = obs.pos;
      const v = obs.vel;
      const att = obs.att;
      const rates = obs.rates;

      if (!initialized) {
        initialized = true;
        vf = { x: v.x, y: v.y, z: v.z };
        prevVf = { x: v.x, y: v.y, z: v.z };
