            Math.abs(gate.y - p.y) < 0.08 &&
            Math.abs(gate.z - p.z) < 0.046 &&
            Math.abs(gate.z - (p.z + vf.z * 0.18)) < 0.052 &&
            Math.abs(vf.x) < 0.22 &&
            Math.abs(vf.y) < 0.18 &&
            Math.abs(vf.z) < 0.12 &&
