            const predZ = p.z + vf.z * tHit + 0.5 * gustZ * tHit * tHit;
            const dy = Math.abs(p.y - gate.y);
            const dz = Math.abs(p.z - gate.z);
            const pdy = Math.abs(predY - gate.y);
            const pdz = Math.abs(predZ - gate.z);
            if (dy > 0.13 || pdy > 0.145 || dz > 0.062 || pdz > 0.072) {
              phase = 'align';
              settle = 0;
              target = { x: gate.x - 0.45, y: gate.y, z: gate.z };
              ref.x = Math.min(target.x, p.x - 0.22);
              intPos.x = 0;
            } else {
              target = { x: Math.min(gate.x + 0.35, p.x + 0.25), y: gate.y, z: gate.z };
            }
